#!/usr/bin/env node
// Emits the OPENCODE_CONFIG_CONTENT JSON for an fm-spawn opencode worker.
//
// Free/completion-only providers are hosted behind the EXISTING opencode agent
// harness as custom @ai-sdk/openai-compatible providers.  The custom-provider
// catalog (data/provider-catalogs/opencode-custom-providers.json, generated by
// bin/fm-provider-discovery.mjs refresh from the live provider catalogs) names
// each provider's baseURL, api key ENV VARIABLE NAME, and its discovered model
// ids.  No secret value is ever emitted: apiKey values are "{env:<VAR>}"
// interpolations the OpenCode client resolves at request time; the keys file is
// sourced by the spawn launcher itself (fm-spawn) so key material never passes
// through a command line or a config file.
//
// Behavior:
// - unknown provider prefix / no catalog file: emit the plain permission config
//   (subscription models via auth.json need no custom provider).
// - known provider but the requested model id is not in that provider's
//   discovered models: refuse (exit 2) so catalog drift fails loudly instead of
//   dispatching on an unverified injected model.

import fs from 'node:fs';

const permissionBlock = { permission: { '*': 'allow' } };

function parseArgs(argv) {
  const flags = {};
  for (let i = 0; i < argv.length; i++) {
    const withValue = argv[i].match(/^--([\w][\w-]*)=(.*)$/);
    if (withValue) { flags[withValue[1]] = withValue[2]; continue; }
    const flagOnly = argv[i].match(/^--([\w][\w-]*)$/);
    if (flagOnly && argv[i + 1] && !argv[i + 1].startsWith('--')) {
      flags[flagOnly[1]] = argv[i + 1];
      i += 1;
      continue;
    }
    if (flagOnly) flags[flagOnly[1]] = true;
  }
  return flags;
}

function parseModelSelector(model) {
  const index = model.indexOf('/');
  if (index <= 0 || index === model.length - 1) return { provider: null, modelId: model };
  return { provider: model.slice(0, index), modelId: model.slice(index + 1) };
}

function main() {
  const flags = parseArgs(process.argv.slice(2));
  const model = typeof flags.model === 'string' ? flags.model : '';
  const { provider, modelId } = parseModelSelector(model);
  const configPath = typeof flags.config === 'string' ? flags.config : '';

  const emit = (extra = {}) => {
    process.stdout.write(JSON.stringify({
      '$schema': 'https://opencode.ai/config.json',
      ...permissionBlock,
      ...extra
    }, null, 0));
    process.stdout.write('\n');
  };

  if (!provider || !configPath || !fs.existsSync(configPath)) {
    emit();
    return 0;
  }
  let catalog;
  try {
    catalog = JSON.parse(fs.readFileSync(configPath, 'utf8'));
  } catch (error) {
    process.stderr.write(`opencode-provider-config: unreadable catalog ${configPath}: ${error.message}\n`);
    return 3;
  }
  const providerDef = catalog.providers?.[provider];
  if (!providerDef) {
    emit();
    return 0;
  }
  if (typeof provider === 'string' && !(providerDef.models?.[modelId])) {
    process.stderr.write(
      `opencode-provider-config: model '${model}' is not in the discovered catalog for provider '${provider}'; refresh the free-provider catalog or choose a discovered model\n`);
    return 2;
  }
  emit({
    provider: {
      [provider]: {
        npm: catalog.npm_package || '@ai-sdk/openai-compatible',
        name: `${provider.toUpperCase()} (free route)`,
        options: {
          baseURL: providerDef.baseURL,
          apiKey: `{env:${providerDef.api_key_env}}`
        },
        models: providerDef.models
      }
    }
  });
  return 0;
}

process.exit(main());
